function createNodeBuild(){
    return (res, rej)=>{
        let count = 0;
        let bat = exec('NODE_ENV=production babel ./src --out-dir ./build/packages --copy-files', { stdio: [0, 1, 2] }, (error, stdout, stderr) => {
              if (error) {
                rej(error);
                return;
              }
        });
        bat.stdout.on('data', (data) => {
          CLI.write(count++, data);
        });
        bat.on('exit', (code) => {
          res(code);
        });
    };
